<?php
require_once __DIR__ . '/../includes/functions.php'; require_staff();
$pdo=db(); $isAdmin=false; $error='';
if($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $action=$_POST['action']??'';
 if($action==='record') { $bookingId=(int)($_POST['booking_id']??0);$amount=(float)($_POST['amount']??0);$method=$_POST['method']??'cash';$ref=trim($_POST['reference_code']??'');$notes=trim($_POST['notes']??'');
  $validMethods=['cash','gcash_manual','bank_transfer','other'];$b=$pdo->prepare("SELECT id,total_amount,status FROM bookings WHERE id=? AND status<>'cancelled'");$b->execute([$bookingId]);$booking=$b->fetch();
  $sum=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM payment_records WHERE booking_id=? AND status='verified'");$sum->execute([$bookingId]);$paid=(float)$sum->fetchColumn();
  if(!$booking||$amount<=0||!in_array($method,$validMethods,true))$error='Choose a valid booking, payment method, and amount.';
  elseif($amount > max(0,(float)$booking['total_amount']-$paid)+0.001)$error='Payment amount exceeds the remaining balance.';
  else { $ins=$pdo->prepare("INSERT INTO payment_records(booking_id,amount,method,reference_code,status,notes,recorded_by) VALUES(?,?,?,?,?,?,?)");$ins->execute([$bookingId,$amount,$method,$ref?:null,'verified',$notes?:null,(int)$_SESSION['user_id']]); if($isAdmin){$u=$pdo->prepare("UPDATE payment_records SET verified_by=?,verified_at=NOW() WHERE id=?");$u->execute([(int)$_SESSION['user_id'],(int)$pdo->lastInsertId()]);} else {$u=$pdo->prepare("UPDATE payment_records SET verified_by=?,verified_at=NOW() WHERE id=?");$u->execute([(int)$_SESSION['user_id'],(int)$pdo->lastInsertId()]);} $result=update_booking_after_verified_payment($pdo,$bookingId); redirect(($isAdmin?'/admin':'/staff').'/payments.php?recorded=1&msg='.urlencode($result['message'])); }
 } elseif($action==='verify' && $isAdmin) { $id=(int)($_POST['payment_id']??0);$decision=$_POST['decision']??'';if(in_array($decision,['verified','rejected'],true)){$u=$pdo->prepare('UPDATE payment_records SET status=?,verified_by=?,verified_at=NOW() WHERE id=? AND status="pending"');$u->execute([$decision,(int)$_SESSION['user_id'],$id]); if($decision==='verified') { $bq=$pdo->prepare('SELECT booking_id FROM payment_records WHERE id=?'); $bq->execute([$id]); $bid=(int)$bq->fetchColumn(); if($bid) update_booking_after_verified_payment($pdo,$bid); }}redirect('/admin/payments.php?updated=1'); }
}
$bookingFilter=(int)($_GET['booking']??0);$rooms=$pdo->query("SELECT b.id,b.booking_code,b.guest_name,b.total_amount,b.check_in,b.check_out,r.name room_name,(SELECT COALESCE(SUM(p.amount),0) FROM payment_records p WHERE p.booking_id=b.id AND p.status='verified') paid FROM bookings b JOIN rooms r ON r.id=b.room_id WHERE b.status<>'cancelled' ORDER BY b.created_at DESC")->fetchAll();
$sql="SELECT p.*,b.booking_code,b.guest_name,r.name room_name,u.name recorder FROM payment_records p JOIN bookings b ON b.id=p.booking_id JOIN rooms r ON r.id=b.room_id LEFT JOIN admins u ON u.id=p.recorded_by ORDER BY p.created_at DESC LIMIT 300";$payments=$pdo->query($sql)->fetchAll();
$pageTitle='Payment recording';include __DIR__.'/../includes/header.php';$base=BASE_URL.'/staff';?>
<section class="admin-page container"><div class="admin-heading"><div><p class="eyebrow">MODULE 4 · PAYMENT RECORDING</p><h1>Payment <em>records.</em></h1><p class="muted">Record deposits and manually verify cash, GCash, or bank-transfer evidence. Manual payments are recorded here; real online checkout is not connected.</p></div><div class="admin-actions"><a class="button button-outline" href="<?= $isAdmin?BASE_URL.'/admin/index.php':BASE_URL.'/staff/index.php' ?>">← Dashboard</a><a class="text-link" href="<?= BASE_URL ?>/<?= $isAdmin?'admin':'staff' ?>/logout.php">Sign out ↗</a></div></div>
<?php if(isset($_GET['recorded'])):?><div class="notice notice-success"><?= e($_GET['msg'] ?? 'Payment received and recorded.') ?></div><?php endif;?><?php if(isset($_GET['updated'])):?><div class="notice notice-success">Payment decision updated.</div><?php endif;?><?php if($error):?><div class="notice notice-warning"><?= e($error) ?></div><?php endif;?>
<div class="admin-room-layout"><div class="add-room-card"><p class="eyebrow">NEW TRANSACTION</p><h2>Record a payment</h2><form method="post" class="booking-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="record"><label>Reservation</label><select name="booking_id" required><option value="">Select a booking</option><?php foreach($rooms as $b):?><option value="<?= (int)$b['id'] ?>" <?= $bookingFilter===(int)$b['id']?'selected':'' ?>><?= e($b['booking_code'].' · '.$b['guest_name'].' · '.$b['room_name'].' · Balance '.money(max(0,(float)$b['total_amount']-(float)$b['paid']))) ?></option><?php endforeach;?></select><label>Amount (₱)</label><input name="amount" type="number" min="1" step="0.01" required><label>Payment method</label><select name="method"><option value="cash">Cash</option><option value="gcash_manual">GCash (manual verification)</option><option value="bank_transfer">Bank transfer</option><option value="other">Other</option></select><label>Reference number (optional)</label><input name="reference_code" maxlength="120"><label>Notes (optional)</label><textarea name="notes" rows="3" maxlength="500"></textarea><p class="fine-print"><?= $isAdmin?'Admin-entered payments are marked verified immediately.':'Staff records payments as received. The system confirms the reservation and emails the customer once verified payments reach the required down payment.' ?></p><button class="button button-dark full-width">Save payment record</button></form></div>
<div class="admin-table-wrap"><div class="table-heading"><div><p class="eyebrow">TRANSACTION HISTORY</p><h2>Recent payments</h2></div></div><div class="table-scroll"><table><thead><tr><th>Booking / Guest</th><th>Amount / Method</th><th>Reference</th><th>Status</th><?php if($isAdmin):?><th>Review</th><?php endif;?></tr></thead><tbody><?php foreach($payments as $pay):?><tr><td><strong><?= e($pay['booking_code']) ?></strong><small><?= e($pay['guest_name']) ?> · <?= e($pay['room_name']) ?><br>Recorded by <?= e($pay['recorder']??'Unknown') ?></small></td><td><?= money($pay['amount']) ?><small><?= e(str_replace('_',' ',$pay['method'])) ?></small></td><td><?= e($pay['reference_code']??'—') ?><small><?= e($pay['notes']??'') ?></small></td><td><span class="status-pill"><?= e($pay['status']) ?></span></td><?php if($isAdmin):?><td><?php if($pay['status']==='pending'):?><form method="post" class="inline-status"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="verify"><input type="hidden" name="payment_id" value="<?= (int)$pay['id'] ?>"><button class="small-button" name="decision" value="verified">Verify</button><button class="small-button" name="decision" value="rejected">Reject</button></form><?php else:?>—<?php endif;?></td><?php endif;?></tr><?php endforeach;?><?php if(!$payments):?><tr><td colspan="<?= $isAdmin?5:4 ?>">No payment records yet.</td></tr><?php endif;?></tbody></table></div></div></div><p class="fine-print">Security note: this records manual payment evidence only. Never store card details, GCash PINs, OTPs, or passwords. Real online payment requires a provider and server-side webhook verification.</p></section>
